const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const data={attendance:[['Rifqi Muhammad A','16 Nov 2026','08:03','17:12','Hadir'],['Yuna Sukmana','16 Nov 2026','07:56','17:05','Hadir'],['Andi Pratama','16 Nov 2026','08:19','—','Terlambat']],work:[['16 Nov 2026','IP-PBX','Pemeriksaan telepon ruang 102','Suara terputus saat panggilan internal','Restart ONT/router dan koneksi kembali normal'],['15 Nov 2026','Lain-lain','Instalasi driver printer','Printer laptop BTS Pajak belum terdeteksi','Instalasi driver terbaru dan uji cetak'],['14 Nov 2026','Lain-lain','Pengecekan token charger mobil','Pengisian token operasional','Pengisian berhasil, daya tercatat 103,8 kWh']],server:[['16/11/2026','Lantai 5','09:15','24°C','48%','Normal','RA'],['16/11/2026','R.610 Kaca','09:18','23°C','49%','Normal','RA'],['15/11/2026','Lantai 5','09:10','24°C','48%','Normal','RA']],reimburse:[['RB-2026-032','15 Nov 2026','Rifqi Muhammad Athallah','Galon & jilid dokumen','Rp108.000','Menunggu'],['RB-2026-031','11 Nov 2026','Andi Pratama','Perlengkapan jaringan','Rp375.000','Disetujui']],request:[['PB-2026-019','15 Nov 2026','Toner HP 85A','2 pcs','Operasional printer','Menunggu'],['PB-2026-018','10 Nov 2026','Kabel LAN Cat6','1 box','Persediaan IT','Disetujui']]};
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};
function status(s){return `<span class="status ${s==='Disetujui'||s==='Hadir'||s==='Normal'?'done':'pending'}">${esc(s)}</span>`}
function render(){ $('#attendanceRows').innerHTML=data.attendance.map(r=>`<tr>${r.slice(0,4).map(x=>`<td>${esc(x)}</td>`).join('')}<td>${status(r[4])}</td></tr>`).join('');$('#workRows').innerHTML=data.work.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}<td><button class="text-btn print-row">⎙</button></td></tr>`).join('');$('#serverRows').innerHTML=data.server.map(r=>`<tr>${r.map((x,i)=>`<td>${i===5?status(x):esc(x)}</td>`).join('')}</tr>`).join('');['reimburse','request'].forEach(k=>{$('#'+k+'Rows').innerHTML=data[k].map(r=>`<tr>${r.map((x,i)=>`<td>${i===r.length-1?status(x):esc(x)}</td>`).join('')}<td><button class="text-btn print-row">⎙</button></td></tr>`).join('')});$('#activity').innerHTML=data.work.slice(0,3).map((r,i)=>`<div class="activity-item"><span class="activity-icon">${i===0?'☎':i===1?'▣':'⚡'}</span><div><b>${esc(r[2])}</b><span>${esc(r[1])} · ${esc(r[0])}</span></div></div>`).join('')}
function show(page){$$('.page').forEach(x=>x.classList.toggle('active-page',x.id===page));$$('.nav[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));const names={dashboard:['OVERVIEW','Selamat pagi, Rifqi'],attendance:['OPERASIONAL','Absensi'],work:['OPERASIONAL','Laporan pekerjaan'],server:['INFRASTRUKTUR','Pengecekan server'],reimburse:['KEUANGAN','Reimbursement'],request:['PENGADAAN','Pengajuan barang'],monthly:['REKAP','Laporan bulanan'],settings:['SISTEM','Pengaturan']};$('#crumb').textContent=names[page][0];$('#pageTitle').textContent=names[page][1];window.scrollTo(0,0)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),2600)}
function printDoc(module){
 const labels={attendance:'Rekap Absensi',work:'Laporan Pekerjaan',server:'Pengecekan Suhu Ruang Server',reimburse:'Surat Permohonan Reimbursement',request:'Pengajuan Barang',monthly:'Laporan Bulanan'};
 if(!labels[module]){toast('Pilih modul laporan yang ingin dicetak terlebih dahulu.');return}
 const period='November 2026', page=$('#'+module), table=page?.querySelector('table');
 let content='';
 if(module==='monthly') content=`<div class="summary"><h2>Ringkasan Operasional</h2><p>Periode ${period}</p><p>Total absensi: <b>18 hadir</b></p><p>Pekerjaan: <b>12 selesai</b></p><p>Pengecekan server: <b>20 normal</b></p><p>Reimbursement: <b>Rp1.108.000</b></p></div>`;
 else if(module==='reimburse') content=`<p>Kepada Yth.<br><b>Manajer terkait</b></p><p>Berikut rincian pengajuan reimbursement periode ${period}.</p>${table.outerHTML}<p>Demikian pengajuan ini dibuat untuk dapat diproses.</p><div class="sign">Pemohon,<br><br><br><b>Administrator OPS</b></div>`;
 else content=table.outerHTML;
 const print=window.open('','_blank','width=900,height=700');
 if(!print){toast('Izinkan pop-up browser untuk mencetak laporan.');return}
 print.document.write(`<!doctype html><html><head><title>${labels[module]} - ${period}</title><style>body{font-family:Arial,sans-serif;color:#111;margin:34px}header{border-bottom:2px solid #172b4d;padding-bottom:15px;margin-bottom:22px}h1{font-size:21px;margin:0}p{font-size:13px;line-height:1.5}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border:1px solid #555;padding:8px;text-align:left;vertical-align:top}th{background:#e9edf2}.summary{max-width:540px}.summary p{border-bottom:1px solid #ddd;padding:9px 0}.sign{text-align:right;margin-top:42px}@page{size:A4 portrait;margin:14mm}@media print{body{margin:0}}</style></head><body><header><h1>OPS REPORT · BANGUN TJIPTA</h1><p>${labels[module]} · Periode ${period}<br>Dicetak: ${new Date().toLocaleDateString('id-ID')}</p></header>${content}</body></html>`);
 print.document.close();print.focus();setTimeout(()=>print.print(),250);
}
function openModal(module){const labels={attendance:'Catat absensi',work:'Laporan pekerjaan',server:'Pemeriksaan suhu server',reimburse:'Pengajuan reimbursement',request:'Pengajuan barang'};$('#modalTitle').textContent=labels[module];const fields=module==='work'?[['Tanggal','date'],['Kategori','text'],['Judul','text'],['Detail permasalahan','textarea'],['Solusi','textarea']]:module==='server'?[['Tanggal','date'],['Ruangan','text'],['Jam','time'],['Suhu (°C)','number'],['Kelembaban (%)','number']]:module==='attendance'?[['Nama karyawan','text'],['Tanggal','date'],['Jam masuk','time'],['Jam pulang','time']]:module==='reimburse'?[['Tanggal','date'],['Keterangan','text'],['Total biaya','number']]:[['Tanggal','date'],['Nama barang','text'],['Jumlah','text'],['Keperluan','text']];$('#formFields').innerHTML=fields.map(([n,t])=>`<label>${n}${t==='textarea'?'<textarea rows="3" required></textarea>':`<input type="${t}" required>`}</label>`).join('');$('#modal').dataset.module=module;$('#modal').classList.remove('hidden')}
$('#loginBtn').onclick=()=>{if($('#email').value&&$('#password').value){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');sessionStorage.opsAuth='1'}else toast('Masukkan email dan kata sandi.')};if(sessionStorage.opsAuth){$('#login').classList.add('hidden');$('#app').classList.remove('hidden')}$('#logout').onclick=()=>{sessionStorage.removeItem('opsAuth');location.reload()};$$('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));$$('[data-new]').forEach(b=>b.onclick=()=>{show(b.dataset.new);setTimeout(()=>openModal(b.dataset.new),100)});$$('.add').forEach(b=>b.onclick=()=>openModal(b.closest('.report-page').dataset.module));$('.close').onclick=()=>$('#modal').classList.add('hidden');$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').classList.add('hidden')};$('#saveEntry').onclick=()=>{const mod=$('#modal').dataset.module, vals=$$('#formFields input,#formFields textarea').map(x=>x.value);if(vals.some(v=>!v)){toast('Lengkapi semua data terlebih dahulu.');return}if(mod==='work')data.work.unshift(vals);else if(mod==='server')data.server.unshift([vals[0],vals[1],vals[2],vals[3]+'°C',vals[4]+'%','Normal','Admin']);else if(mod==='attendance')data.attendance.unshift([vals[0],vals[1],vals[2],vals[3],'Hadir']);else if(mod==='reimburse')data.reimburse.unshift(['RB-2026-'+(33+data.reimburse.length),vals[0],'Admin',vals[1],'Rp'+Number(vals[2]).toLocaleString('id-ID'),'Menunggu']);else data.request.unshift(['PB-2026-'+(20+data.request.length),vals[0],vals[1],vals[2],vals[3],'Menunggu']);render();$('#modal').classList.add('hidden');toast('Laporan berhasil disimpan.');};$$('.import input').forEach(input=>input.onchange=e=>{if(e.target.files[0])toast('File dipilih. Hubungkan parser Excel di backend untuk impor produksi.')});$('#printAll').onclick=()=>{const active=$('.report-page.active-page');printDoc(active?.id)};$('#monthlyPrint').onclick=()=>printDoc('monthly');document.addEventListener('click',e=>{const button=e.target.closest('[data-print],.print-row');if(button)printDoc(button.dataset.print||button.closest('.report-page')?.id)});$$('[data-copy]').forEach(b=>b.onclick=()=>{navigator.clipboard?.writeText(b.dataset.copy);toast('Panduan konfigurasi: gunakan environment variable '+b.dataset.copy+' di deployment.');});render();
